export const meta = {
  name: 'coverage-audit-verify',
  description: 'Verify each item flagged by coverage_audit.py against the JCStream repo',
  phases: [
    { title: 'Verify', detail: 'one agent per flagged group, checks all real consumers' },
    { title: 'Refute', detail: 'adversarial second pass on claimed real gaps' },
  ],
}

const REPO = 'C:/Users/jared/Documents/GitHub/HCJC'

const COMMON = `Repo: ${REPO} (JCStream, static public-records site). An audit script flagged items as "produced but unsurfaced with no stated reason". The script is crude: it counts a field as produced if the regex "(\\w+)"\\s*: matches anywhere in web/shape/*.py (so lookup-table keys, kwargs dicts, and JSON-parsing keys all count), and counts it surfaced ONLY if the bare identifier appears inside {{ }} or {% %} in web/templates/*.html. Real consumers it cannot see: web/static/main.js, web/templates/feed.xml or any non-.html template, web/build.py writing the field into published JSON under docs/data/, JSON-LD blocks, and fields that are members of dicts serialized wholesale into a published feed (anything landing in docs/data/*.json IS public surface). Your job: for each item below, find the truth. Use Grep/Read on the repo. Verdicts: FALSE_POSITIVE (not actually a shaped output field, e.g. regex noise like a platform check or internal lookup key), SURFACED (it does reach a public surface; say exactly where, file:line), REAL_GAP (genuinely produced/stored, reaches no public surface, and you found no comment/doc stating a reason), WITHHELD (you found an explicit stated reason in code comments, CLAUDE.md, audit/ docs, or README). Give file:line evidence for every verdict.`

const FIELD_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['item', 'verdict', 'evidence', 'detail'],
        properties: {
          item: { type: 'string' },
          verdict: { type: 'string', enum: ['FALSE_POSITIVE', 'SURFACED', 'REAL_GAP', 'WITHHELD'] },
          evidence: { type: 'string', description: 'file:line references' },
          detail: { type: 'string', description: 'one or two sentences, what this item actually is and where it goes or stops' },
        },
      },
    },
  },
}

const GROUPS = [
  { key: 'bond.p10', prompt: `${COMMON}\n\nItems, all flagged from web/shape/bond.py: "p10". Read web/shape/bond.py, find where p10 is produced and every place the containing dict travels (templates, build.py, published JSON).` },
  { key: 'common.win32', prompt: `${COMMON}\n\nItem flagged from web/shape/common.py: "win32". Read web/shape/common.py and determine what this key actually is.` },
  { key: 'court.*', prompt: `${COMMON}\n\nItems flagged from web/shape/court.py: "civil", "criminal", "date_text", "traffic". Read web/shape/court.py, trace each key: is it parsed input, internal grouping, or shaped output? Where does the containing structure go (templates, courtclerk_cases.json, docs/data)?` },
  { key: 'feeds.*', prompt: `${COMMON}\n\nItems flagged from web/shape/feeds.py: "booked", "released", "updated". Read web/shape/feeds.py, trace each key to its consumer. Check web/templates/feed.xml and any RSS/atom template, main.js, and published JSON.` },
  { key: 'inmates.*', prompt: `${COMMON}\n\nItems flagged from web/shape/inmates.py: "events_recent", "hours". Read web/shape/inmates.py, trace both keys through build.py and all templates including _card.html and inmate.html.` },
  { key: 'files.unpublished', prompt: `${COMMON}\n\nItems: two files exist in data/ but not in docs/data/: incidents_recent.json and oi_shootings_recent.json. For each: find the writer (scraper/*.py, .github/workflows/sweep.yml), find whether web/build.py reads it (rendered into HTML counts as SURFACED), whether anything copies it to docs/data, and whether any comment/doc states why it is not published. data/ is committed to a public GitHub repo, but the site surface is docs/. Note if oi_shootings_recent.json overlaps shootings_recent.json (which IS published).` },
  { key: 'files.undeclared', prompt: `${COMMON}\n\nItems: six files are served under docs/data/ but the audit script claims the /data/ page does not link them: cca_complaints_recent.json, crime_stars_recent.json, pedestrian_stops_recent.json, traffic_stops_drivers_recent.json, use_of_force_incidents_recent.json, use_of_force_pdi_recent.json. The script used a HARDCODED list of declared files; do not trust it. Read web/templates/data.html (and any other template that lists downloadable feeds, e.g. stats.html, base.html footer) and determine for each of the six whether a public link or mention actually exists. Verdict SURFACED if linked, REAL_GAP if truly unlisted.` },
]

const REFUTE_SCHEMA = {
  type: 'object',
  required: ['refuted', 'reason'],
  properties: {
    refuted: { type: 'boolean', description: 'true if you found a consumer, stated reason, or evidence the item is not a real gap' },
    reason: { type: 'string', description: 'file:line evidence' },
  },
}

phase('Verify')
const verified = await pipeline(
  GROUPS,
  g => agent(g.prompt, { label: `verify:${g.key}`, phase: 'Verify', schema: FIELD_SCHEMA }),
  (res, g) => {
    if (!res) return { key: g.key, results: [] }
    const gaps = res.results.filter(r => r.verdict === 'REAL_GAP')
    if (!gaps.length) return { key: g.key, results: res.results }
    return parallel(gaps.map(gap => () =>
      agent(`${COMMON}\n\nA first-pass verifier claims this is a REAL_GAP (produced/stored, no public surface, no stated reason): item "${gap.item}" (group ${g.key}). Their evidence: ${gap.evidence}. Their detail: ${gap.detail}\n\nTry hard to REFUTE this. Search web/static/main.js, ALL files in web/templates/ (any extension), web/build.py, docs/data/*.json contents (grep for the field name inside the JSON), scraper/*.py comments, CLAUDE.md, audit/*.md, README files. If you find a consumer or a stated withholding reason, refuted=true with file:line. If after genuinely searching you find nothing, refuted=false.`,
        { label: `refute:${gap.item}`, phase: 'Refute', schema: REFUTE_SCHEMA })
        .then(v => ({ ...gap, refuted: v ? v.refuted : false, refuteReason: v ? v.reason : 'refuter died' }))
    )).then(refutes => {
      const merged = res.results.map(r => {
        const ref = refutes.filter(Boolean).find(x => x.item === r.item)
        return ref ? ref : r
      })
      return { key: g.key, results: merged }
    })
  }
)

const flat = verified.filter(Boolean).flatMap(v => v.results.map(r => ({ group: v.key, ...r })))
return { flat }

