def _tally_attribute(inmates: list[Inmate], attr: str, expand) -> list[tuple[str, int]]:
    """Count inmates by a demographic attribute, returning (label, count) descending."""
    out: dict[str, int] = {}
    for inm in inmates:
        label = expand(getattr(inm, attr, ""))
        out[label] = out.get(label, 0) + 1
    return sorted(out.items(), key=lambda kv: -kv[1])


def _tier_summary(inmates: list[Inmate]) -> dict[str, int]:
    """Count inmates by primary tier kind (felony/misdemeanor/other)."""
    tiers: dict[str, int] = {"felony": 0, "misdemeanor": 0, "other": 0}
    for inm in inmates:
        t = _primary_tier(inm)
        tiers[t["kind"] if t else "other"] += 1
    return tiers


def _inmate_bond_total(inmate: Inmate) -> float | None:
    """Sum all parseable bond amounts for an inmate; None if no amounts found."""
    total = 0.0
    any_amt = False
    for c in inmate.charges:
        amt = _parse_bond_amount(c.bond_amount)
        if amt is not None:
            any_amt = True
            total += amt
    return total if any_amt else None


def _bond_stats(inmates: list[Inmate]) -> dict:
    """Aggregate bond statistics across all inmates."""
    bond_vals: list[float] = []
    zero_bond = 0
    for inm in inmates:
        total = _inmate_bond_total(inm)
        if total is not None:
            bond_vals.append(total)
            if total == 0:
                zero_bond += 1
    bond_vals.sort()
    return {
        "bond_total": sum(bond_vals),
        "bond_median": bond_vals[len(bond_vals) // 2] if bond_vals else 0,
        "bond_zero": zero_bond,
        "bond_known": len(bond_vals),
    }


def _charge_stats(inmates: list[Inmate]) -> dict:
    """Aggregate charge-count statistics across all inmates."""
    n = len(inmates)
    ch_counts = [len(inm.charges) for inm in inmates]
    avg_ch = (sum(ch_counts) / n) if n else 0
    return {
        "avg_charges": round(avg_ch, 1),
        "max_charges": max(ch_counts) if ch_counts else 0,
        "one_charge": sum(1 for c in ch_counts if c == 1),
    }


def _custody_stats(inmates: list[Inmate]) -> dict:
    """Aggregate days-in-custody statistics across all inmates."""
    days = [d for inm in inmates if (d := _days_in_custody(inm)) is not None]
    avg_days = (sum(days) / len(days)) if days else 0
    return {"avg_days": round(avg_days), "max_days": max(days) if days else 0}


def _compute_stats(snapshot: Snapshot, by_month) -> dict:
    """Aggregates for the /stats/ page."""
    inmates = snapshot.inmates
    n = len(inmates)
    with_photo = sum(1 for inm in inmates if inm.photo_filename)
    return {
        "n": n,
        "months": [(m, len(g)) for m, g in by_month],
        "offenses": _crimes_of_month(inmates),
        "tiers": _tier_summary(inmates),
        "sex": _tally_attribute(inmates, "sex", _expand_sex),
        "race": _tally_attribute(inmates, "race", _expand_race),
        **_bond_stats(inmates),
        **_charge_stats(inmates),
        "with_photo": with_photo,
        "no_photo": n - with_photo,
        **_custody_stats(inmates),
        "tier_breakdown": _tier_breakdown(snapshot),
        "top_offenses": _top_offenses_with_orc(snapshot, top_n=12),
        "court_calendar": _upcoming_courts(snapshot, days_ahead=14),
        "slippage": _court_slippage(inmates),
    }

def _resolve_site_url() -> str:
    """Absolute site origin (no trailing slash) for feeds / manifest / JSON-LD.

    1. ``JCSTREAM_SITE_URL`` env var (explicit, e.g. ``https://www.aretheyinjail.com``)
    2. ``https://<JCSTREAM_CNAME>`` if a custom domain is configured
    3. Derived from GitHub Actions: ``https://<owner>.github.io/<repo>``
    4. Fallback: ``https://aicincy.github.io/JCStream``
    """
    explicit = os.environ.get("JCSTREAM_SITE_URL", "").strip()
    if explicit:
        return explicit.rstrip("/")
    cname = (os.environ.get("JCSTREAM_CNAME", "") or "").strip()
    if cname:
        return "https://" + cname.rstrip("/")
    repo = os.environ.get("GITHUB_REPOSITORY", "")
    if "/" in repo:
        owner, name = repo.split("/", 1)
        return f"https://{owner.lower()}.github.io/{name}"
    return "https://aicincy.github.io/JCStream"


# Dispatch geocoding extracted to web/dispatch.py.

        # Take the first plausible match from the highest-priority pattern
        # rather than falling through to a broader pattern the moment one
        # token fails the clamp (e.g. "99" is not 2099, but a later token in
        # the same format might be the real year).
        for m in rx.finditer(s):
            year = 2000 + int(m.group(1))
            if year <= max_year:
                return year
    return None


def _charge_tier(charge, offenses: dict | None = None) -> dict | None:
    """Determine felony/misdemeanor tier for a charge.

    Returns {label: str, kind: 'felony' | 'misdemeanor'} or None.

    Extraction order:
    1. Degree suffix in charge description (e.g., "ASSAULT F4" -> F4)
    2. ORC lookup in offenses dict (if available)
    3. Venue inference: Common Pleas -> felony, Municipal -> misdemeanor
    4. None if no signal found
    """
    if hasattr(charge, "description") and charge.description:
        m = _DEGREE_RE.search(str(charge.description))
        if m:
            deg = m.group(1)
            kind = "felony" if deg.startswith("F") else "misdemeanor"
            return {"label": deg, "kind": kind}

    # Try ORC lookup.
    if offenses and hasattr(charge, "orc_code") and charge.orc_code:
        code = str(charge.orc_code).strip()
        if code.upper() != "NONE":
            from scraper import orc as orc_mod

            deg = orc_mod.degree_for(code, offenses)
            if deg and deg != "?":
                kind = "felony" if deg.startswith("F") else "misdemeanor"
                return {"label": deg, "kind": kind}

    # Fallback: infer from case number venue.
    if hasattr(charge, "common_pleas_case") and charge.common_pleas_case and str(charge.common_pleas_case).strip():
        return {"label": "F", "kind": "felony"}
    if hasattr(charge, "municipal_case") and charge.municipal_case and str(charge.municipal_case).strip():
        return {"label": "M", "kind": "misdemeanor"}

    return None


def _tier_counts(inmate, offenses: dict | None = None) -> dict[str, int]:
    """Count charges by tier for an inmate.

    Returns {felony: int, misdemeanor: int, unknown: int}.
    """
    counts = {"felony": 0, "misdemeanor": 0, "unknown": 0}
    for charge in inmate.charges:
        tier = _charge_tier(charge, offenses)
        if tier:
            key = "felony" if tier["kind"] == "felony" else "misdemeanor"
            counts[key] += 1
        else:
            counts["unknown"] += 1
    return counts


def _primary_tier(inmate, offenses: dict | None = None) -> dict | None:
    """Get the tier of the inmate's most serious charge.

    Returns {label, kind} or None if no charges have a determinable tier.
    """
    if not hasattr(inmate, "charges"):
        return None
    best_tier = None
    best_idx = len(_DEGREE_ORDER)
    for charge in inmate.charges:
        tier = _charge_tier(charge, offenses)
        if not tier or not tier.get("label"):
            continue
        deg = tier["label"]
        if deg in _DEGREE_ORDER:
            idx = _DEGREE_ORDER.index(deg)
            if idx < best_idx:
                best_tier, best_idx = tier, idx
    return best_tier


def _primary_degree(inmate, offenses: dict | None = None) -> str:
    """Get the degree (F1, M2, etc.) of the inmate's most serious charge."""
    tier = _primary_tier(inmate, offenses)
    return tier["label"] if tier else "UNK"

