.kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  margin: 18px 0 24px;
}
.kpi {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px 24px;
  box-shadow: var(--shadow-card);
  transition: box-shadow 140ms, transform 140ms, border-color 140ms;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .kpi:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); border-color: var(--accent); }
}
.kpi .label {
  color: var(--fg-muted);
  font-size: 11.5px;
  margin-bottom: 8px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.kpi .num {
  font-family: var(--font-sans);
  font-size: clamp(20px, 2.4vw, 32px);
  font-weight: 700;
  color: var(--fg);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  line-height: 1;
  margin-top: auto;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi:first-child {
  background: var(--surface);
  border-color: transparent;
  color: var(--fg);
}
.kpi:first-child .label { color: var(--accent); }
.kpi:first-child .num { color: var(--fg); }
