file.content:
/* Collapsible section-h: same visual rhythm as <div class="section-h"> so a
   <details> wrapping a section reads as a peer of the other H2 sections,
   not as a separate card-style toggle. Used on stats.html for the court
   calendar. */
.section-h-details { margin: 0 0 24px; }
.section-h-details > summary {
  display: flex; align-items: flex-end; gap: 14px;
  margin: 28px 0 16px; flex-wrap: wrap;
  cursor: pointer; list-style: none;
}
.section-h-details > summary::-webkit-details-marker { display: none; }
.section-h-details > summary::before {
  content: "▸"; display: inline-block; align-self: center;
  font-size: 11px; color: var(--fg-muted);
  transition: transform 120ms;
