(function(){
  var out = {};
  out.kpis = Array.from(document.querySelectorAll('.kpi')).map(function(k){
    var l=k.querySelector('.label'), n=k.querySelector('.num'), f=k.querySelector('.kpi-foot');
    return (l?l.textContent.trim():'') + ' = ' + (n?n.textContent.trim():'') + (f?' ('+f.textContent.trim()+')':'');
  });
  out.stamp = (document.querySelector('.stamp')||{}).textContent;
  out.seg_first = document.querySelector('.stacked-seg') ? getComputedStyle(document.querySelector('.stacked-seg')).backgroundColor : null;
  out.seg_count = document.querySelectorAll('.stacked-seg').length;
  out.footer = (document.querySelector('footer.site span')||{}).textContent;
  return out;
})()

(function(){
  var folds = Array.from(document.querySelectorAll('details.section-h-details'));
  var toc = document.querySelectorAll('.courts-toc a').length;
  var open = folds.filter(function(d){return d.open}).map(function(d){return d.id});
  var pageHeight = document.body.scrollHeight;
  var t = folds.find(function(d){return d.id==='probate'});
  t && (location.hash = '#probate');
  return {folds: folds.length, tocLinks: toc, openByDefault: open, pageHeight: pageHeight, probateOpensViaHash: t ? t.open : 'missing'};
})()

(function(){
  var probate = document.getElementById('probate');
  var rows = Array.from(document.querySelectorAll('body > *, main .page > *')).slice(0,40).map(function(el){
    var h = el.offsetHeight||0;
    return h > 400 ? (el.tagName + '#' + (el.id||'') + '.' + (el.className||'').toString().slice(0,30) + ' = ' + h) : null;
  }).filter(Boolean);
  return {probateNowOpen: probate ? probate.open : null, tall: rows};
})()

